(()=>{const dismissedKey='moodnote-popup-dismissed-v2',today=()=>new Date().toISOString().slice(0,10);function shouldShow(settings){if(!settings?.enabled)return false;const date=today();if(settings.startDate&&date<settings.startDate)return false;if(settings.endDate&&date>settings.endDate)return false;if(localStorage.getItem(dismissedKey)===date||sessionStorage.getItem(dismissedKey)==='1')return false;return true}function close(backdrop){const daily=backdrop.querySelector('[data-popup-daily]').checked;if(daily)localStorage.setItem(dismissedKey,today());else sessionStorage.setItem(dismissedKey,'1');backdrop.remove();document.body.style.removeProperty('overflow')}function show(settings){if(!shouldShow(settings)||document.querySelector('.store-popup-backdrop'))return;const backdrop=document.createElement('div');backdrop.className=`store-popup-backdrop ${settings.position||'center'}`;backdrop.innerHTML=`<article class="store-popup ${settings.theme||'cherry'}" role="dialog" aria-modal="true" aria-labelledby="store-popup-title"><button data-popup-close aria-label="팝업 닫기">×</button><small>WELCOME TO MOODNOTE</small><h2 id="store-popup-title">${escapeHTML(settings.title)}</h2><p>${escapeHTML(settings.message)}</p><a href="${escapeHTML(settings.buttonLink||'#catalog')}" data-popup-link>${escapeHTML(settings.buttonLabel||'자세히 보기')}</a><label><input type="checkbox" data-popup-daily/> 오늘 하루 보지 않기</label></article>`;document.body.append(backdrop);document.body.style.overflow='hidden';backdrop.addEventListener('click',event=>{if(event.target===backdrop||event.target.closest('[data-popup-close]'))close(backdrop);if(event.target.closest('[data-popup-link]'))close(backdrop)})}function escapeHTML(value){return String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}window.addEventListener('moodnote-popup',event=>show(event.detail.popup))})();
